(function(global){
  'use strict';
  const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const defaultBusiness={name:'Ateliê Aurora',description:'Produtos artesanais feitos com cuidado.',hours:'Segunda a sexta, 9h às 17h',greeting:'Olá! Obrigada por entrar em contato. Como posso ajudar?',away:'Recebemos sua mensagem. Vamos responder durante o horário de atendimento.',quick:['Olá! Posso explicar os materiais e tamanhos.','Obrigada pelo interesse! Vou confirmar o prazo e retorno.'],labels:['Novo contato','Aguardando resposta','Pedido de treino'],activeLabel:'Novo contato',messages:[{from:'client',text:'Olá! Você pode me contar o tamanho e o material da peça?',time:'10:14'}],catalog:[{name:'Caneca artesanal',price:'R$ 35,00',description:'Cerâmica em tom terroso, peça de demonstração.'},{name:'Camiseta dobrada',price:'R$ 49,00',description:'Tecido leve, exemplo de catálogo.'}]};
  function readBusiness(){try{const data=JSON.parse(localStorage.getItem('metalab-business-v1')||'null');return data&&typeof data==='object'?{...structuredClone(defaultBusiness),...data}:structuredClone(defaultBusiness)}catch{return structuredClone(defaultBusiness)}}
  let business=readBusiness(),waTab='chats',waView='list',waToast='';
  function saveBusiness(){try{localStorage.setItem('metalab-business-v1',JSON.stringify(business))}catch{waToast='Sem espaço local para salvar; a atividade continua nesta sessão.'}}
  function tabs(items,active){return `<nav class="sim-tabs" aria-label="Seções">${items.map(([key,label])=>`<button type="button" data-tab="${key}" class="${active===key?'active':''}" aria-current="${active===key?'page':'false'}">${label}</button>`).join('')}</nav>`}
  function businessFrame(panel,header,bindBack,title,body){panel.classList.add('sim-app');panel.innerHTML=`${header(title)}<div class="app-body">${body}</div>`;bindBack()}
  function renderWhatsApp(panel,header,bindBack){
    let body=`<div class="sim-note">WhatsApp Business de treino. Contato, catálogo e mensagens são fictícios e ficam somente neste navegador.</div>${tabs([['chats','Conversas'],['catalog','Catálogo'],['tools','Ferramentas']],waTab)}`;
    if(waTab==='chats'){
      if(waView==='list')body+=`<div class="sim-card" style="padding:0"><button class="wa-contact" id="waOpenChat"><span class="wa-avatar">C</span><span style="flex:1"><b>Cliente de treino</b><small>${escapeHtml(business.messages.at(-1)?.text||'Começar conversa')}</small></span><span class="wa-badge">${escapeHtml(business.activeLabel)}</span></button></div><div class="sim-card"><h3>Treine um atendimento claro</h3><p>Abra a conversa, escolha uma resposta rápida ou escreva a sua. Nada será enviado a outra pessoa.</p></div>`;
      else body+=`<div class="sim-card sim-row"><span><b style="font-size:10px">Cliente de treino</b><br><small class="sim-muted">${escapeHtml(business.activeLabel)}</small></span><button type="button" class="secondary" id="waBackList">Voltar</button></div><div class="wa-thread" id="waThread">${business.messages.map(m=>`<div class="wa-bubble ${m.from==='me'?'mine':''}">${escapeHtml(m.text)}<small>${escapeHtml(m.time)}</small></div>`).join('')}</div><div class="wa-chips">${business.quick.map((q,i)=>`<button type="button" data-quick="${i}">${escapeHtml(q)}</button>`).join('')}</div><form class="wa-composer" id="waForm"><input class="sim-field" id="waText" maxlength="300" placeholder="Mensagem de treino" aria-label="Mensagem de treino" required><button type="submit" aria-label="Enviar mensagem fictícia">➤</button></form><div class="sim-card"><label class="sim-label" for="waLabel">Etiqueta do contato</label><select class="sim-field" id="waLabel">${business.labels.map(l=>`<option ${l===business.activeLabel?'selected':''}>${escapeHtml(l)}</option>`).join('')}</select><button type="button" class="sim-button secondary" id="waResetChat">Reiniciar conversa</button></div>`;
    }else if(waTab==='catalog'){
      body+=`<div class="sim-card"><h3>Catálogo do negócio</h3><p>Exemplos de produtos para aprender a apresentar nome, preço e descrição.</p></div>${business.catalog.map((p,i)=>`<div class="sim-card wa-product"><div class="wa-product-art">${i===0?'☕':'▤'}</div><span style="flex:1"><strong>${escapeHtml(p.name)}</strong><small>${escapeHtml(p.price)} · ${escapeHtml(p.description)}</small></span><button type="button" class="sim-button secondary" data-share="${i}">Enviar na conversa</button></div>`).join('')}<div class="sim-card"><h3>Adicionar produto fictício</h3><form id="waProductForm"><input class="sim-field" name="name" maxlength="40" placeholder="Nome do produto" required><input class="sim-field" name="price" maxlength="24" placeholder="Preço de exemplo" required><input class="sim-field" name="description" maxlength="100" placeholder="Descrição curta" required><button class="sim-button" type="submit">Adicionar ao catálogo</button></form></div>`;
    }else{
      body+=`<div class="sim-card"><h3>Perfil comercial</h3><label class="sim-label" for="waName">Nome</label><input class="sim-field" id="waName" maxlength="40" value="${escapeHtml(business.name)}"><label class="sim-label" for="waDescription">Descrição</label><input class="sim-field" id="waDescription" maxlength="100" value="${escapeHtml(business.description)}"><label class="sim-label" for="waHours">Horário de atendimento</label><input class="sim-field" id="waHours" maxlength="70" value="${escapeHtml(business.hours)}"><button class="sim-button" id="waSaveProfile">Salvar perfil</button></div><div class="sim-card"><h3>Mensagens automáticas de treino</h3><label class="sim-label" for="waGreeting">Saudação</label><input class="sim-field" id="waGreeting" maxlength="150" value="${escapeHtml(business.greeting)}"><label class="sim-label" for="waAway">Ausência</label><input class="sim-field" id="waAway" maxlength="150" value="${escapeHtml(business.away)}"><button class="sim-button" id="waSaveAutomations">Salvar mensagens</button><div class="sim-row" style="margin-top:8px"><button class="secondary" data-test-auto="greeting">Testar saudação</button><button class="secondary" data-test-auto="away">Testar ausência</button></div><div class="wa-status">O teste apenas coloca o texto na conversa fictícia.</div></div><div class="sim-card"><h3>Respostas rápidas</h3>${business.quick.map((q,i)=>`<div class="sim-row" style="margin:5px 0"><span style="font-size:8px">${escapeHtml(q)}</span><button type="button" class="secondary" data-remove-quick="${i}" aria-label="Excluir resposta rápida">×</button></div>`).join('')}<form id="waQuickForm"><input class="sim-field" name="quick" maxlength="150" placeholder="Nova resposta rápida" required><button class="sim-button" type="submit">Adicionar resposta</button></form></div><div class="sim-card"><h3>Etiquetas</h3><p>${business.labels.map(escapeHtml).join(' · ')}</p><form id="waLabelForm"><input class="sim-field" name="label" maxlength="25" placeholder="Nova etiqueta" required><button class="sim-button secondary" type="submit">Criar etiqueta</button></form></div>`;
    }
    if(waToast)body+=`<div class="sim-note" role="status">${escapeHtml(waToast)}</div>`;
    businessFrame(panel,header,bindBack,'WhatsApp Business',body);panel.querySelector('.app-top').classList.add('wa-header');
    panel.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{waTab=b.dataset.tab;waView='list';waToast='';renderWhatsApp(panel,header,bindBack)});
    const byId=id=>panel.querySelector('#'+id);
    if(byId('waOpenChat'))byId('waOpenChat').onclick=()=>{waView='chat';renderWhatsApp(panel,header,bindBack)};
    if(byId('waBackList'))byId('waBackList').onclick=()=>{waView='list';renderWhatsApp(panel,header,bindBack)};
    if(byId('waForm')){byId('waForm').onsubmit=e=>{e.preventDefault();const value=byId('waText').value.trim();if(!value)return;business.messages.push({from:'me',text:value,time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})});saveBusiness();renderWhatsApp(panel,header,bindBack);panel.querySelector('.wa-thread')?.scrollIntoView({block:'end'})};panel.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{byId('waText').value=business.quick[Number(b.dataset.quick)];byId('waText').focus()});byId('waLabel').onchange=e=>{business.activeLabel=e.target.value;saveBusiness();renderWhatsApp(panel,header,bindBack)};byId('waResetChat').onclick=()=>{business.messages=structuredClone(defaultBusiness.messages);saveBusiness();renderWhatsApp(panel,header,bindBack)}}
    panel.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>{const p=business.catalog[Number(b.dataset.share)];business.messages.push({from:'me',text:`${p.name} — ${p.price}. ${p.description}`,time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})});saveBusiness();waTab='chats';waView='chat';renderWhatsApp(panel,header,bindBack)});
    if(byId('waProductForm'))byId('waProductForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.currentTarget);business.catalog.push({name:String(form.get('name')).trim(),price:String(form.get('price')).trim(),description:String(form.get('description')).trim()});saveBusiness();waToast='Produto de treino adicionado.';renderWhatsApp(panel,header,bindBack)};
    if(byId('waSaveProfile'))byId('waSaveProfile').onclick=()=>{business.name=byId('waName').value.trim()||defaultBusiness.name;business.description=byId('waDescription').value.trim();business.hours=byId('waHours').value.trim();saveBusiness();waToast='Perfil salvo neste navegador.';renderWhatsApp(panel,header,bindBack)};
    if(byId('waSaveAutomations'))byId('waSaveAutomations').onclick=()=>{business.greeting=byId('waGreeting').value.trim();business.away=byId('waAway').value.trim();saveBusiness();waToast='Mensagens preparadas e salvas localmente.';renderWhatsApp(panel,header,bindBack)};
    panel.querySelectorAll('[data-test-auto]').forEach(b=>b.onclick=()=>{const kind=b.dataset.testAuto;const value=(kind==='greeting'?byId('waGreeting'):byId('waAway')).value.trim();if(!value)return;business[kind]=value;business.messages.push({from:'me',text:`[${kind==='greeting'?'Saudação':'Ausência'} de treino] ${value}`,time:new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})});saveBusiness();waTab='chats';waView='chat';renderWhatsApp(panel,header,bindBack)});
    if(byId('waQuickForm'))byId('waQuickForm').onsubmit=e=>{e.preventDefault();const value=String(new FormData(e.currentTarget).get('quick')).trim();if(value)business.quick.push(value);saveBusiness();renderWhatsApp(panel,header,bindBack)};
    panel.querySelectorAll('[data-remove-quick]').forEach(b=>b.onclick=()=>{business.quick.splice(Number(b.dataset.removeQuick),1);saveBusiness();renderWhatsApp(panel,header,bindBack)});
    if(byId('waLabelForm'))byId('waLabelForm').onsubmit=e=>{e.preventDefault();const value=String(new FormData(e.currentTarget).get('label')).trim();if(value&&!business.labels.includes(value))business.labels.push(value);saveBusiness();renderWhatsApp(panel,header,bindBack)};
  }

  const instagramDb='metalab-pocket-instagram';let dbPromise,igTab='feed',igFile=null,igPreviewUrl='',igPostUrls=[];
  function openDb(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(instagramDb,1);request.onupgradeneeded=()=>request.result.createObjectStore('posts',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}
  async function dbAction(mode,method,record){const db=await openDb();return new Promise((resolve,reject)=>{const tx=db.transaction('posts',mode);const request=tx.objectStore('posts')[method](record);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
  function clearPostUrls(){igPostUrls.forEach(URL.revokeObjectURL);igPostUrls=[]}
  async function renderInstagram(panel,header,bindBack,message=''){
    clearPostUrls();let records=[];try{records=(await dbAction('readonly','getAll')).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))}catch{message='O armazenamento local de fotos não está disponível neste navegador.'}
    let body=`<div class="sim-note">Instagram de treino: suas imagens ficam neste navegador. Não há conta, seguidores nem publicação externa.</div>${tabs([['feed','Publicações'],['create','Criar'],['profile','Perfil']],igTab)}`;
    if(igTab==='feed')body+=records.length?records.map(p=>{const url=URL.createObjectURL(p.blob);igPostUrls.push(url);return `<article class="ig-post"><div class="ig-post-head"><span class="wa-avatar">M</span><span>metalab.pocket · treino</span></div><img src="${url}" alt="Foto publicada na simulação"><div class="ig-post-actions"><button type="button" data-like="${escapeHtml(p.id)}" class="${p.liked?'liked':''}" aria-label="${p.liked?'Descurtir':'Curtir'} publicação">${p.liked?'♥':'♡'}</button><button type="button" data-delete="${escapeHtml(p.id)}" aria-label="Excluir publicação de treino">⌫</button></div><div class="ig-caption"><b>${p.liked?'1 curtida · ':''}${new Date(p.createdAt).toLocaleDateString('pt-BR')}</b><br>${escapeHtml(p.caption||'Sem legenda')}</div></article>`}).join(''):'<div class="ig-empty">Nenhuma publicação de treino ainda.<br>Abra “Criar” para escolher uma foto do computador.</div>';
    else if(igTab==='create')body+=`<div class="sim-card"><h3>Nova publicação de treino</h3><label class="ig-upload">Escolher foto do computador<input id="igFile" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Escolher foto do computador"></label><p id="igFileName">${igFile?escapeHtml(igFile.name):'PNG, JPEG ou WebP · até 8 MB'}</p><img id="igPreview" class="ig-preview ${igPreviewUrl?'ready':''}" src="${igPreviewUrl}" alt="Prévia da foto escolhida"><label class="sim-label" for="igCaption">Legenda</label><textarea class="sim-field" id="igCaption" rows="3" maxlength="300" placeholder="Descreva o produto com clareza"></textarea><div class="ig-count" id="igCount">0/300</div><button type="button" class="sim-button" id="igPublish" ${igFile?'':'disabled'}>Publicar na simulação</button><p id="igFeedback" role="status"></p></div>`;
    else body+=`<div class="sim-card"><div class="sim-row"><span class="wa-avatar">M</span><span><b style="font-size:10px">MetaLab Pocket</b><br><small class="sim-muted">@metalab.pocket · perfil fictício</small></span></div><hr class="sim-divider"><p>Um espaço para praticar fotos, legendas e apresentação de produtos com orientação do instrutor.</p><p><b>${records.length}</b> publicaç${records.length===1?'ão':'ões'} de treino neste navegador.</p></div>${records.length?`<div class="sim-card"><h3>Minhas fotos</h3><div class="saved-photo-grid">${records.map(p=>{const url=URL.createObjectURL(p.blob);igPostUrls.push(url);return `<img src="${url}" alt="Foto da publicação de treino">`}).join('')}</div></div>`:''}`;
    if(message)body+=`<div class="sim-note" role="status">${escapeHtml(message)}</div>`;
    if(panel.dataset.currentApp!=='vitrine'||!panel.classList.contains('open'))return;
    businessFrame(panel,header,bindBack,'Instagram',body);panel.querySelector('.app-top').classList.add('ig-header');panel.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{igTab=b.dataset.tab;renderInstagram(panel,header,bindBack)});
    panel.querySelectorAll('[data-like]').forEach(b=>b.onclick=async()=>{const record=records.find(p=>p.id===b.dataset.like);if(!record)return;record.liked=!record.liked;await dbAction('readwrite','put',record);renderInstagram(panel,header,bindBack)});
    panel.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{await dbAction('readwrite','delete',b.dataset.delete);renderInstagram(panel,header,bindBack,'Publicação removida deste navegador.')});
    const fileInput=panel.querySelector('#igFile');if(fileInput)fileInput.onchange=()=>{const file=fileInput.files?.[0];const feedback=panel.querySelector('#igFeedback');if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024){feedback.textContent='Escolha PNG, JPEG ou WebP de até 8 MB.';fileInput.value='';return}if(igPreviewUrl)URL.revokeObjectURL(igPreviewUrl);igFile=file;igPreviewUrl=URL.createObjectURL(file);const preview=panel.querySelector('#igPreview');preview.src=igPreviewUrl;preview.classList.add('ready');panel.querySelector('#igFileName').textContent=file.name;panel.querySelector('#igPublish').disabled=false};
    const caption=panel.querySelector('#igCaption');if(caption){caption.oninput=()=>panel.querySelector('#igCount').textContent=`${caption.value.length}/300`;panel.querySelector('#igPublish').onclick=async()=>{if(!igFile)return;const button=panel.querySelector('#igPublish');button.disabled=true;try{await dbAction('readwrite','put',{id:crypto.randomUUID?.()||String(Date.now()),blob:igFile,caption:caption.value.trim(),createdAt:new Date().toISOString(),liked:false});igFile=null;if(igPreviewUrl)URL.revokeObjectURL(igPreviewUrl);igPreviewUrl='';igTab='feed';renderInstagram(panel,header,bindBack,'Foto publicada somente nesta simulação.')}catch{button.disabled=false;panel.querySelector('#igFeedback').textContent='Não foi possível guardar a foto neste navegador.'}}}
  }
  global.MetaLabBusinessApps={renderWhatsApp,renderInstagram};
})(window);
